package org.apache.lucene.geo;

import static org.apache.lucene.geo.XYEncodingUtils.checkVal;

/**
 * Represents a point on the earth's surface. You can construct the point directly with {@code
 * double} coordinates.
 *
 * <p>NOTES:
 *
 * <ol>
 *   <li>latitude/longitude values must be in decimal degrees.
 *   <li>For more advanced GeoSpatial indexing and query operations see the {@code spatial-extras}
 *       module
 * </ol>
 */
public final class XYPoint extends XYGeometry {

  /** latitude coordinate */
  private final float x;

  /** longitude coordinate */
  private final float y;

  /** Creates a new Point from the supplied latitude/longitude. */
  public XYPoint(float x, float y) {
    this.x = checkVal(x);
    this.y = checkVal(y);
  }

  /** Returns latitude value at given index */
  public float getX() {
    return x;
  }

  /** Returns longitude value at given index */
  public float getY() {
    return y;
  }

  @Override
  protected Component2D toComponent2D() {
    return Point2D.create(this);
  }

  /** Compute bounding box for this point at the given radius. */
  public XYRectangle boundingRectangle(float radius) {
    checkVal(x);
    checkVal(y);
    if (radius < 0) {
      throw new IllegalArgumentException("radius must be bigger than 0, got " + radius);
    }
    if (Float.isFinite(radius) == false) {
      throw new IllegalArgumentException("radius must be finite, got " + radius);
    }
    float distanceBox = Math.nextUp(radius);
    float minX = Math.max(-Float.MAX_VALUE, x - distanceBox);
    float maxX = Math.min(Float.MAX_VALUE, x + distanceBox);
    float minY = Math.max(-Float.MAX_VALUE, y - distanceBox);
    float maxY = Math.min(Float.MAX_VALUE, y + distanceBox);
    return new XYRectangle(minX, maxX, minY, maxY);
  }

  private boolean sameCoordinates(XYPoint other) {
    XYRectangle thisBounds = boundingRectangle(Math.nextUp(0f));
    XYRectangle otherBounds = other.boundingRectangle(Math.nextUp(0f));
    if (thisBounds.minX > x
        || x > thisBounds.maxX
        || thisBounds.minY > y
        || y > thisBounds.maxY) {
      return false;
    }
    if (otherBounds.minX > other.x
        || other.x > otherBounds.maxX
        || otherBounds.minY > other.y
        || other.y > otherBounds.maxY) {
      return false;
    }
    return other.x == x && other.y == y;
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) return true;
    if (!(o instanceof XYPoint)) return false;
    return sameCoordinates((XYPoint) o);
  }

  @Override
  public int hashCode() {
    int result = Float.hashCode(x);
    result = 31 * result + Float.hashCode(y);
    return result;
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Point(");
    sb.append(x);
    sb.append(",");
    sb.append(y);
    sb.append(')');
    return sb.toString();
  }
}

